from html.parser import HTMLParser
from pathlib import Path

html = Path('index.html').read_text()

class Parser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.buttons = []
        self.details = {}
        self.main_count = 0
        self.h1_count = 0
    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        classes = set(attrs.get('class', '').split())
        self.stack.append((tag, classes, attrs))
        if tag == 'main':
            self.main_count += 1
        if tag == 'h1':
            self.h1_count += 1
        if tag == 'button' and 'question' in classes:
            self.buttons.append(attrs)
            if attrs.get('aria-expanded') != 'false':
                raise SystemExit('A question is not collapsed by default')
            if 'aria-controls' not in attrs:
                raise SystemExit('A question is missing aria-controls')
        if 'details' in classes:
