const buttonControls = [...html.matchAll(/<button class="question" type="button" aria-expanded="false" aria-controls="([^"]+)"/g)].map((match) => match[1]);
if (buttonControls.length !== 5) throw new Error(`Expected 5 collapsed question buttons, found ${buttonControls.length}`);

for (const id of buttonControls) {
  const detailsPattern = new RegExp(`<div class="details" id="${id}" hidden>`);
  if (!detailsPattern.test(html)) throw new Error(`Missing hidden .details panel for ${id}`);
}

console.log('Static FAQ checks passed');
